 if($action==='post'){ $p=['title'=>trim($_POST['title']??''),'slug'=>slugify($_POST['slug']??$_POST['title']??''),'date'=>$_POST['date']??date('Y-m-d'),'type'=>trim($_POST['type']??'Article'),'author'=>trim($_POST['author']??'YonoLootZone'),'description'=>trim($_POST['description']??''),'excerpt'=>trim($_POST['excerpt']??''),'image'=>safe_asset($_POST['image']??''),'imageAlt'=>trim($_POST['imageAlt']??''),'video'=>trim($_POST['video']??''),'content'=>$_POST['content']??'']; if(!$p['title']||!$p['description']||!$p['content']){$error='Title, meta description and content are required.';}else{$posts=read_json(CMS_DATA.'/posts.json',[]);$posts=array_values(array_filter($posts,fn($x)=>($x['slug']??'')!==$p['slug']));$posts[]=$p;write_json(CMS_DATA.'/posts.json',$posts);$dir=SITE_ROOT.'/posts/'.$p['slug'];if(!is_dir($dir))mkdir($dir,0755,true);file_put_contents($dir.'/index.html',render_post($p),LOCK_EX);update_sitemap(SITE_URL.'/posts/'.$p['slug'].'/');update_posts_index($posts);$notice='Post published: /posts/'.$p['slug'].'/';}}
